/*
 * Generates the SRL Lezer parser from `src/lib/srlLanguage/srl.grammar`.
 *
 *   pnpm --filter @sparql-query-lib/web build:srl-parser
 *
 * The generated files are committed. A build step that produced them would
 * have to run before typecheck, before vitest, before nuxt, and in every
 * editor — four places to remember for a file that changes when the grammar
 * does, which is rarely. `test/lib/srlLanguage.test.ts` regenerates in memory
 * and fails if what is on disk has drifted, so "committed" cannot mean "stale".
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildParserFile } from '@lezer/generator';

const here = dirname(fileURLToPath(import.meta.url));
const dir = join(here, '..', 'src', 'lib', 'srlLanguage');

export const grammarPath = join(dir, 'srl.grammar');
/*
 * `.generated.ts` rather than `.ts`: `scripts/count-any.mjs` skips generated
 * files, and the parser tables carry two `any`s of lezer's own that no one here
 * can remove.
 */
export const parserPath = join(dir, 'parser.generated.ts');
export const termsPath = join(dir, 'parser.terms.generated.ts');

const HEADER = '// Generated by scripts/build-srl-parser.mjs from srl.grammar. Do not edit.\n';

/** The parser and terms modules the grammar currently implies, as text. */
export function generate() {
  const grammar = readFileSync(grammarPath, 'utf8');
  const { parser, terms } = buildParserFile(grammar, {
    fileName: grammarPath,
    moduleStyle: 'es',
    typeScript: true,
    // Term names cost a few KB and buy readable trees in tests and in the
    // Lezer inspector, which is where anyone touching this grammar will be.
    includeNames: true,
  });
  return { parser: HEADER + parser, terms: HEADER + terms };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const { parser, terms } = generate();
  writeFileSync(parserPath, parser);
  writeFileSync(termsPath, terms);
  console.log(`wrote ${parserPath}`);
  console.log(`wrote ${termsPath}`);
}
